const a=__dmh.audio; const P=document.getElementById('pause'); P.style.display='flex';
const set=(k,v)=>{const el=P.querySelector('input[data-k="'+k+'"]'); el.value=v; el.dispatchEvent(new Event('input'));};
const rd=()=>({out:+a._out.gain.value.toFixed(3), sfx:a.sfxBus?+a.sfxBus.gain.value.toFixed(2):null, dry:a.sfxDry?+a.sfxDry.gain.value.toFixed(2):null, music:a.musicGain?+a.musicGain.gain.value.toFixed(2):('vol '+a.musicVol), world:+a.master.gain.value.toFixed(2), gun:+a.gunBus.gain.value.toFixed(2)});
const r0=rd(); set('sfx',0.3); const r1=rd(); set('volume',0.4); const r2=rd(); set('music',1); const r3=rd(); set('sfx',1); set('volume',0.8); set('music',0.5);
JSON.stringify({labels:[...P.querySelectorAll('label span')].map(s=>s.textContent), r0,r1,r2,r3, saved:localStorage.getItem('dmh-settings')||Object.keys(localStorage).join(',')})
